/* Bundled Study pack catalog (data/study/packs-v1.json, generated by scripts/build-study-packs.mjs and
 * byte-identical to the apps' assets/study/packs-v1.json). Loading, lookup and country ordering, the same
 * rules as Android's StudyPackCatalog: own country first, then packs listing it as nearby, then global. */
(function (root, factory) {
    const api = factory();
    if (typeof module === 'object' && module.exports) module.exports = api;
    else root.FilterTubeStudyPacks = api;
}(typeof globalThis !== 'undefined' ? globalThis : this, function () {
    'use strict';

    const CATALOG_PATH = 'data/study/packs-v1.json';
    const SCHEMA = 'filtertube_study_packs';
    const VERSION = 1;
    const GLOBAL_PREFIX = 'global_';
    /**
     * Study-picker kinds; "exam" and "class" are the v2 names, "interview" is job-interview prep (global
     * packs with their own setup tile). Kids packs are "kids_age" and "kids_classic".
     */
    const STUDY_KINDS = Object.freeze(['study', 'exam', 'class', 'interview', 'degree']);
    const KIDS_KINDS = Object.freeze(['kids_age', 'kids_classic']);
    const PACK_ID = /^[A-Za-z0-9_.-]{1,64}$/;
    let cached = null;

    function array(value) { return Array.isArray(value) ? value : []; }
    function text(value) { return typeof value === 'string' ? value.trim() : ''; }
    function strings(value) { return array(value).map(text).filter(Boolean); }
    function normalizeHandle(value) { return text(value).replace(/^@/, '').toLowerCase(); }

    function parseChannel(row) {
        if (!row || typeof row !== 'object') return null;
        const channelId = text(row.channelId) || null;
        const handle = text(row.handle) || null;
        const name = text(row.name);
        if ((!channelId && !handle) || !name) return null;
        // country: the channel's audience, an ISO country ("IN"), "global", or null when the curators didn't say.
        return { channelId, handle, name, language: text(row.language) || null, country: text(row.country) || null };
    }

    /** {"en": "Tamil Nadu", "ta": "..."}: a label per language, keys lowercased, blanks dropped. */
    function parseLabels(value) {
        const out = {};
        if (!value || typeof value !== 'object' || Array.isArray(value)) return out;
        for (const [lang, label] of Object.entries(value)) if (text(lang) && text(label)) out[text(lang).toLowerCase()] = text(label);
        return out;
    }

    function parseGradeKeywords(value) {
        const out = {};
        if (!value || typeof value !== 'object' || Array.isArray(value)) return out;
        for (const [grade, words] of Object.entries(value)) {
            const list = strings(words);
            if (text(grade) && list.length) out[text(grade)] = list;
        }
        return out;
    }

    function parseNames(value) {
        const names = {};
        for (const [lang, name] of Object.entries(value && typeof value === 'object' ? value : {})) {
            if (text(name)) names[lang] = text(name);
        }
        return names;
    }

    /** Branches or streams (GATE CSE, ECE, ...): their own chips, extra topics and the pack channels that teach them. */
    function parseVariants(value) {
        const out = [];
        for (const row of array(value)) {
            const id = text(row?.id);
            if (!PACK_ID.test(id) || out.some(variant => variant.id === id)) continue;
            out.push({
                id,
                names: parseNames(row.name),
                chips: strings(row.chips),
                keywords: strings(row.keywords),
                channels: strings(row.channels),
                isDefault: row.default === true
            });
        }
        return out;
    }

    /** Validates and reads a catalog; rows the apps would skip are skipped here too. */
    function parseCatalog(value) {
        if (!value || typeof value !== 'object' || value.schema !== SCHEMA) throw new Error('Not a study pack catalog');
        if (value.version !== VERSION) throw new Error(`Unsupported study pack catalog version ${value.version}`);
        const packs = [];
        for (const json of array(value.packs)) {
            const id = text(json?.id);
            if (!PACK_ID.test(id)) continue;
            const names = parseNames(json.name);
            packs.push({
                id,
                kind: text(json.kind) || 'study',
                names,
                countries: strings(json.countries).map(code => code.toUpperCase()),
                nearby: strings(json.nearby).map(code => code.toUpperCase()),
                languages: strings(json.languages),
                subjects: strings(json.subjects),
                keywords: strings(json.keywords),
                // Class packs: the grade band ("6-8"), the board, and topic words per grade.
                grade: text(json.grade) || null,
                board: text(json.board) || null,
                gradeKeywords: parseGradeKeywords(json.gradeKeywords),
                blockedWords: strings(json.blockedWords),
                // The exam's short label ("GATE"), the study Home's subject chips and the branches.
                shortName: text(json.shortName) || null,
                // Interview packs: the career group setup lists them under ("software", "management", "law", ...).
                group: text(json.group) || null,
                // Exam packs: "regional" for a state or province exam (area names it), else national;
                // category is the picker's (school, entrance, civil, professional, language).
                level: text(json.level) || null,
                area: parseLabels(json.area),
                category: text(json.category) || null,
                // Degree packs: the specialization their track sits under ({"en": "Mechanical engineering"}).
                specialization: parseLabels(json.specialization),
                chips: strings(json.chips),
                variants: parseVariants(json.variants),
                // True when the variants are levels of one syllabus (JEE Main and Advanced), not branches.
                variantsShareTopics: json.variantsShareTopics === true,
                channels: array(json.channels).map(parseChannel).filter(Boolean)
            });
        }
        return Object.freeze({ version: VERSION, packs });
    }

    /** Loads the bundled catalog once. Pass fetch and getURL (runtime.getURL) outside extension pages. */
    async function load({ fetch: fetchFn = globalThis.fetch, getURL = null } = {}) {
        if (cached) return cached;
        const runtime = globalThis.chrome?.runtime || globalThis.browser?.runtime;
        const resolve = getURL || (runtime?.getURL ? path => runtime.getURL(path) : path => path);
        if (typeof fetchFn !== 'function') throw new Error('Study packs cannot be loaded here');
        const response = await fetchFn(resolve(CATALOG_PATH));
        if (!response || response.ok === false) throw new Error('Study packs could not be loaded');
        cached = parseCatalog(await response.json());
        return cached;
    }

    function resetCache() { cached = null; }

    /** The user's country from a locale such as "en-IN" or "hi_IN"; empty when it names none. */
    function countryFromLocale(locale) {
        const parts = text(locale).replace(/_/g, '-').split('-').slice(1);
        return parts.find(part => /^[A-Za-z]{2}$/.test(part))?.toUpperCase() || '';
    }

    /** A pack for everyone: an id starting "global_", or one with no country. */
    function isGlobal(pack) {
        return text(pack?.id).startsWith(GLOBAL_PREFIX) || array(pack?.countries).length === 0;
    }

    /**
     * Packs for someone in `country`: that country's own packs first, then packs that list it as nearby,
     * then global packs. Within each group the catalog order is kept; no pack repeats.
     */
    function forCountry(catalog, country, { kinds = STUDY_KINDS } = {}) {
        const code = text(country).toUpperCase();
        const valid = code.length === 2 ? code : '';
        const candidates = array(catalog?.packs).filter(pack => kinds.includes(pack.kind));
        const own = valid ? candidates.filter(pack => pack.countries.includes(valid)) : [];
        const nearby = valid ? candidates.filter(pack => pack.nearby.includes(valid)) : [];
        const global = candidates.filter(isGlobal);
        const seen = new Set();
        return [...own, ...nearby, ...global].filter(pack => !seen.has(pack.id) && seen.add(pack.id));
    }

    /**
     * The picker's tabs: "exams" (kind study/exam) and "school" (kind class), for a country, and
     * "kids": Kids learning by age (the classic decades aren't study).
     */
    function forTab(catalog, country, tab) {
        if (tab === 'kids') return array(catalog?.packs).filter(pack => pack.kind === 'kids_age');
        return forCountry(catalog, country, { kinds: tab === 'school' ? ['class'] : ['study', 'exam'] });
    }

    function kidsPacks(catalog) {
        return array(catalog?.packs).filter(pack => KIDS_KINDS.includes(pack.kind));
    }

    function packById(catalog, id) {
        return array(catalog?.packs).find(pack => pack.id === text(id)) || null;
    }

    /** The name in `language`, else English, else any. */
    function packName(pack, language) {
        const names = pack?.names || {};
        const lang = text(language).toLowerCase().split(/[-_]/)[0];
        return (lang && names[lang]) || names.en || Object.values(names)[0] || text(pack?.id);
    }

    /**
     * The pack channel that is this channel, or null. A channel id decides when both sides have one
     * (handles can change hands); otherwise the handle, compared without "@" and case.
     */
    function matchChannel(pack, channelId, handle) {
        const id = text(channelId);
        const wanted = normalizeHandle(handle);
        const channels = array(pack?.channels);
        if (id) {
            const byId = channels.find(channel => channel.channelId === id);
            if (byId) return byId;
        }
        if (!wanted) return null;
        return channels.find(channel => (!id || !channel.channelId) && channel.handle && normalizeHandle(channel.handle) === wanted) || null;
    }

    /** The chosen variant, else the default one, else the first; null when the pack has none. */
    function packVariant(pack, id) {
        const variants = array(pack?.variants);
        return variants.find(variant => variant.id === text(id)) || variants.find(variant => variant.isDefault) || variants[0] || null;
    }

    function variantName(variant, language) {
        const names = variant?.names || {};
        const lang = text(language).toLowerCase().split(/[-_]/)[0];
        return (lang && names[lang]) || names.en || Object.values(names)[0] || text(variant?.id);
    }

    function packsForChannel(catalog, channelId, handle) {
        return array(catalog?.packs).filter(pack => matchChannel(pack, channelId, handle));
    }

    // ---- Country accent (Android CountryAccent.kt) ------------------------------------------------
    // Study setup's light country accent: a short crayon stripe in colours from the country's flag
    // palette (never the flag itself), an optional doodle motif, and one mark colour. Decoration only:
    // brick stays the only action colour, so a flag red never becomes the mark (the mark is the first
    // non-red stripe colour, else Study's sage). Every colour clears 3:1 as a mark on paper, the page and
    // the washed card, light and dark; the card's 6 % wash keeps ink, muted text and brick at 4.5:1.

    /** One crayon colour per theme (0xRRGGBB); `red` keeps it out of the mark slot. */
    const crayon = (light, dark, red = false) => Object.freeze({ light, dark, red });
    const GREEN = crayon(0x2F6B45, 0x7DBE93);
    const RED = crayon(0xB0364A, 0xEE8A93, true);
    const CRIMSON = crayon(0xA3263A, 0xEF8E98, true);
    const MAROON = crayon(0x8A2E35, 0xE39A9F, true);
    const SAFFRON = crayon(0xA8581A, 0xF0A35E);
    const GOLD = crayon(0x86650F, 0xE5C062);
    const BLUE = crayon(0x2D5A9E, 0x8DB4EA);
    const NAVY = crayon(0x2E4C8F, 0x93ACE6);
    const CHARCOAL = crayon(0x4A4A48, 0xC4C8CC);
    /** Study's sage (BrandPalette sageMark): the default accent. */
    const SAGE = crayon(0x3E7D5B, 0x7FB89A);
    /** BrandPalette paper, light and night. */
    const PAPER = Object.freeze({ light: 0xFFFCF6, dark: 0x151C24 });
    const ACCENT_WASH = 0.06;
    // DoodleKit motifs (STAR_SPARKLE, FLOWER) as the extension's doodles.
    const STAR = 'star';
    const FLOWER = 'flower';
    const ACCENT_TABLE = Object.freeze({
        IN: [[SAFFRON, NAVY, GREEN]], PK: [[GREEN], STAR], BD: [[GREEN, RED]], NP: [[CRIMSON, NAVY]],
        LK: [[MAROON, SAFFRON, GREEN]], ID: [[RED]], PH: [[BLUE, RED, GOLD], STAR], NG: [[GREEN]],
        KE: [[CHARCOAL, RED, GREEN]], EG: [[RED, GOLD, CHARCOAL]], SA: [[GREEN]], AE: [[GREEN, RED, CHARCOAL]],
        TR: [[RED], STAR], BR: [[GREEN, GOLD, BLUE], STAR], MX: [[GREEN, RED]], ES: [[RED, GOLD]],
        DE: [[CHARCOAL, RED, GOLD]], FR: [[BLUE, RED]], GB: [[NAVY, RED]], US: [[NAVY, RED], STAR],
        JP: [[RED], FLOWER], KR: [[RED, BLUE]], VN: [[RED, GOLD], STAR], TH: [[RED, NAVY]]
    });
    const ACCENT_CODES = Object.freeze(Object.keys(ACCENT_TABLE));

    /** `base` moved `amount` of the way to `over` (0xRRGGBB). */
    function blendColor(base, over, amount) {
        const ch = shift => {
            const a = (base >> shift) & 0xFF;
            const b = (over >> shift) & 0xFF;
            return Math.min(255, Math.max(0, Math.trunc(a + (b - a) * amount)));
        };
        return (ch(16) << 16) | (ch(8) << 8) | ch(0);
    }

    function cssColor(value) { return `#${(value & 0xFFFFFF).toString(16).padStart(6, '0')}`; }

    function makeAccent(code, stripes, motif = null) {
        const markCrayon = stripes.find(item => !item.red) || SAGE;
        const tone = night => (night ? 'dark' : 'light');
        return Object.freeze({
            code, motif, isDefault: code === null, stripeCrayons: Object.freeze(stripes.slice()),
            /** The stripe's colours in this theme, left to right (one to three). */
            stripes: night => stripes.map(item => item[tone(night)]),
            /** Dots and squiggle: the first non-red stripe colour, else sage. */
            mark: night => markCrayon[tone(night)],
            /** The country card's paper with a breath of the mark (6 %). */
            wash: night => (code === null ? PAPER[tone(night)] : blendColor(PAPER[tone(night)], markCrayon[tone(night)], ACCENT_WASH))
        });
    }

    const DEFAULT_ACCENT = makeAccent(null, [SAGE]);

    /** The accent for a country code ("IN", "jp"); a country without an entry, or none, gets sage. */
    function countryAccent(country) {
        const code = text(country).toUpperCase();
        const row = ACCENT_TABLE[code];
        return row ? makeAccent(code, row[0], row[1] || null) : DEFAULT_ACCENT;
    }

    return Object.freeze({
        CATALOG_PATH, SCHEMA, VERSION, STUDY_KINDS, KIDS_KINDS,
        load, resetCache, parseCatalog, countryFromLocale, isGlobal, forCountry, forTab, kidsPacks, packById, packName,
        matchChannel, packsForChannel, packVariant, variantName,
        ACCENT_CODES, DEFAULT_ACCENT, countryAccent, blendColor, cssColor
    });
}));
